import json,statistics as st,collections
from pathlib import Path
p=Path('/Users/sun/.loom/reviews/2026-10-23-browser-metrics')
xs=[json.loads(l) for l in (p/'results.jsonl').read_text().splitlines()]
def stat(v):return {'n':len(v),'median':round(st.median(v),2),'min':round(min(v),2),'max':round(max(v),2)}
loads={};samples=[]
for arm in ['before','after']:
 for cache in ['cold','warm']:
  z=[x for x in xs if x['kind']=='load' and x['sample'].startswith('run-') and x['arm']==arm and x['cache']==cache];assert len(z)==6
  def fcp(x):return next((p['startTime'] for p in x['paint'] if p['name']=='first-contentful-paint'),0)
  loads[arm+'-'+cache]={'readyMs':stat([x['readyMs'] for x in z]),'fcpMs':stat([fcp(x) for x in z]),'transferBytes':stat([sum(r['transfer'] for r in x['resources']) for x in z]),'resourceCount':stat([len(x['resources']) for x in z]),'longTaskTotalMs':stat([sum(t['duration'] for t in x['longTasks']) for x in z])}
  for x in z:samples.append({'arm':arm,'cache':cache,'sample':x['sample'],'readyMs':x['readyMs'],'fcpMs':fcp(x),'transferBytes':sum(r['transfer'] for r in x['resources']),'resourceCount':len(x['resources']),'visibility':x['visibility']})
g=collections.defaultdict(list);counts=collections.Counter();clickSamples=[]
for x in xs:
 if x['kind']=='click' and x['sample'] in ['click-0','click-1','click-2','click-3']:
  k=(x['arm'],x['sample'],x['label']);cycle=counts[k];counts[k]+=1
  assert cycle<2
  g[(x['arm'],x['label'],cycle)].append(x['duration']);clickSamples.append({k:x[k] for k in ['arm','sample','label','duration','visibility']}|{'cycle':cycle})
clicks={f'{a}/{l}/'+('first' if c==0 else 'repeat'):stat(v) for (a,l,c),v in g.items()}
assert len(clicks)==24 and all(x['n']==4 for x in clicks.values())
x=next(x for x in xs if x['kind']=='load' and x['sample']=='run-5' and x['arm']=='after' and x['cache']=='warm')
largest=sorted(x['resources'],key=lambda r:r['transfer'],reverse=True)[:10]
tls=json.loads((p/'tls.json').read_text());tlsSummary={s:stat([x['totalMs'] for x in tls if x['scheme']==s]) for s in ['http','https']}
summary={'implementation':'5f61d227','baseline':'2a2a3b08 (same frontend as d157e8c4 docs commit)','method':{'browser':'Existing Chrome extension session, 1440x1000; no CPU/network throttle','data':'Same live backend and same channel; 54 message DOM elements verified each navigation, no visible alert. Role 44, instance 70. No messages or role configurations changed; normal read acknowledgements allowed.','frontend':'Original immutable deployment assets served through two identical localhost benchmark gateways; same gzip policy. Cold=no-store HTTP cache bypass, not a fresh browser/JIT process. Warm=primed browser cache.','ready':'Existing composer + message content present without alert, then two animation frames; not FCP or TTI. Resource totals at ready+400ms; resource timing API transferSize, excludes navigation document and probe script.','click':'Captured real click -> target page visible -> two frames. Measures page presentation, NOT complete async data readiness or INP.','order':'6 alternating before/after pairs per cache arm, 24 successful navigations. 4 complete paired click journeys, each 6 pages x 2 cycles = 96 recorded clicks.','probe':'Test-only observer served before app scripts; does not simulate clicks. Browser clicks via CUA. Same observer in both arms.','instrumentationCorrections':['Initial pilot rejected because local runtime /v1 endpoint was not proxied; final runs forward it and have zero blocked requests.','Initial warm Agent measurement used DOM existence and was missing due retained hidden node; final runs require CSS visibility.','Pilot numbers from progress messages superseded by final sample table.']},'loads':loads,'clicks':clicks,'largestWarmResources':largest,'tlsHtmlFetch':{'method':'12 alternating requests per scheme over same LAN IP; new urllib connections, verified local CA; not browser rendering or remote LAN device','summaryMs':tlsSummary},'failures':[{'arm':'before','sample':'click-4','observed':'Two rapid computer-to-task transitions did not reach tasks marker within browser wait deadline; page remained Computers. Subsequent explicit task click worked. Partial journey excluded in full from paired timing statistics, retained as failure.','classification':'Unresolved navigation/input reliability observation, not proven 30-second rendering latency; cannot identify cause from timing alone.'}],'limits':['Chrome HTTP controlled benchmark is not Firefox LAN HTTPS end-to-end acceptance.','Existing browser process/JIT and OS cache stay warm even in no-store arm.','Four complete click pairs are small-sample descriptive evidence, not p95/causal significance.','No usable official authenticated Raft browser comparator; no Raft parity claim.','CUA tabs reported visibility visible even after opening another test tab; native Chrome control unavailable, so no real hidden-tab polling count claimed. Prior deterministic hook tests remain evidence for hidden pause.','First minute stutter not reproduced or closed by these short samples.'],'conclusion':'Resource reduction proved (2 requests and about12.5KB transfer per cold startup); no consistent end-user latency improvement proved. Existing page first-open delay and repeated API payloads are more promising follow-up targets.','rawLocalDirectory':str(p)}
out=Path('docs/evo/evidence/2026-10-23-browser-metrics');out.mkdir(exist_ok=True)
for name,data in [('summary.json',summary),('samples.json',{'loads':samples,'clicks':clickSamples,'tls':tls})]:(out/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(loads,indent=2));print(json.dumps(clicks,ensure_ascii=False));print('largest',largest)
